INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m30903$nota-0180$m30903$, $m30904$Manual treinamento.pdf$m30904$, $m30905$96$m30905$, $m30906$À medida que a fadiga aumenta: altera-se o recrutamento muscular; aumenta a coativação; modificam-se padrões biomecânicos; cresce o custo energético. Esse fenômeno contribui para explicar a redução progressiva do desempenho em provas muito longas. Nos últimos anos, esse tema passou a ser estudado sob o conceito de durabilidade.$m30906$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m30907$nota-0180$m30907$, $m30908$nota-0081$m30908$, $m30909$complementa$m30909$, $m30910$fornece o mecanismo fisiológico (degradação da economia de pedalada) por trás da queda de Stamina/resistência à fadiga sub-FTP já operacionalizada na nota-0081 do Livro 1$m30910$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m30911$nota-0180$m30911$, $m30912$nota-0179$m30912$, $m30913$pre-requisito$m30913$, $m30914$depende da definição de economia estabelecida na nota-0179$m30914$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m30915$nota-0181$m30915$, $m30916$Manual treinamento.pdf$m30916$, $m30917$99$m30917$, $m30918$durabilidade pode ser definida como: A capacidade de manter as características fisiológicas e o desempenho mecânico ao longo do tempo, apesar da fadiga acumulada.$m30918$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m30919$nota-0181$m30919$, $m30920$Manual treinamento.pdf$m30920$, $m30921$101$m30921$, $m30922$Um dos principais indicadores de baixa durabilidade é a incapacidade de sustentar a potência produzida no início da competição... Isso demonstra que potência máxima e durabilidade representam capacidades distintas.$m30922$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m30923$nota-0181$m30923$, $m30924$nota-0081$m30924$, $m30925$complementa$m30925$, $m30926$o conceito de durabilidade descrito aqui é a base teórica do que o Livro 1 já operacionaliza como Stamina/resistência à fadiga sub-FTP (nota-0081) e TTE (nota-0080)$m30926$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m30927$nota-0182$m30927$, $m30928$Manual treinamento.pdf$m30928$, $m30929$100$m30929$, $m30930$Sistema cardiovascular: deriva cardíaca; redução do volume sistólico; aumento da frequência cardíaca para mesma potência.$m30930$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m30931$nota-0182$m30931$, $m30932$Manual treinamento.pdf$m30932$, $m30933$99$m30933$, $m30934$O Atleta B perde progressivamente potência, aumenta a frequência cardíaca relativa, reduz sua eficiência de pedalada e deixa de acompanhar o grupo principal.$m30934$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m30935$nota-0182$m30935$, $m30936$Manual treinamento.pdf$m30936$, $m30937$160$m30937$, $m30938$Durante exercícios prolongados é comum observar aumento progressivo da frequência cardíaca, mesmo mantendo potência constante. Esse fenômeno recebe o nome de deriva cardíaca. Entre seus principais fatores estão: aumento da temperatura corporal; redução do volume plasmático; desidratação; fadiga cardiovascular. Quando interpretada corretamente, a deriva cardíaca pode fornecer informações importantes sobre: resistência aeróbia; estado de hidratação; adaptação ao treinamento.$m30938$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m30939$nota-0182$m30939$, $m30940$nota-0001$m30940$, $m30941$complementa$m30941$, $m30942$decoupling Pw:Hr do Livro 1 (nota-0001), citado no corpo da nota como o fenômeno operacional cujo mecanismo fisiológico é a deriva cardíaca descrita aqui — link estrutural ausente até auditoria de 2026-08-02$m30942$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m30943$nota-0193$m30943$, $m30944$Manual treinamento.pdf$m30944$, $m30945$146$m30945$, $m30946$Monotonia: refere-se à repetição de cargas semelhantes ao longo da semana. Treinamentos excessivamente repetitivos aumentam o risco de fadiga e doenças. Strain: representa a combinação entre carga total e monotonia. Altos valores de strain estão associados a maior probabilidade de queda de desempenho e lesões.$m30946$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m30947$nota-0195$m30947$, $m30948$Manual treinamento.pdf$m30948$, $m30949$150$m30949$, $m30950$A fadiga periférica ocorre nos músculos e estruturas envolvidas diretamente na contração... A fadiga central envolve alterações no sistema nervoso central. Ela manifesta-se por redução do comando motor enviado aos músculos... Em provas extremamente longas, a fadiga central assume importância crescente.$m30950$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m30951$nota-0195$m30951$, $m30952$nota-0180$m30952$, $m30953$complementa$m30953$, $m30954$a fadiga periférica é um dos mecanismos por trás da degradação de economia de pedalada descrita na nota-0180$m30954$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m30955$nota-0196$m30955$, $m30956$Manual treinamento.pdf$m30956$, $m30957$152$m30957$, $m30958$Após um estímulo adequado: ocorre fadiga; inicia-se a recuperação; o organismo ultrapassa temporariamente o nível inicial de desempenho; caso novo estímulo seja aplicado nesse momento, ocorre evolução progressiva. Entretanto, a supercompensação não deve ser interpretada como uma curva simples e universal. Diferentes capacidades apresentam tempos distintos de recuperação: glicogênio muscular; força máxima; capacidade aeróbia; sistema nervoso; tecido conjuntivo.$m30958$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m30959$nota-0196$m30959$, $m30960$nota-0148$m30960$, $m30961$complementa$m30961$, $m30962$fornece o modelo teórico geral (supercompensação) por trás da distinção prática já registrada na nota-0148 entre overreached agudo e overtraining crônico$m30962$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m30963$nota-0197$m30963$, $m30964$Manual treinamento.pdf$m30964$, $m30965$161$m30965$, $m30966$A VFC representa uma estimativa indireta da atividade do sistema nervoso autônomo. Valores reduzidos podem indicar: fadiga; estresse; recuperação incompleta. Entretanto, sua interpretação exige cuidado. A VFC apresenta grande variabilidade individual. Por isso, tendências ao longo do tempo são mais úteis do que valores isolados.$m30966$);
